const crypto = require('crypto');

function hashPassword(password, salt) {
  return crypto.createHash('sha256').update(salt + password).digest('hex');
}

function generateSalt() {
  return crypto.randomBytes(16).toString('hex');
}

function generateToken() {
  return crypto.randomUUID();
}

function tokenExpires(hours = 24) {
  return new Date(Date.now() + hours * 3600000).toISOString();
}

function isExpired(isoDate) {
  if (!isoDate) return true;
  return new Date(isoDate) < new Date();
}

function isValidEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function isValidTime(time) {
  return /^([01]?\d|2[0-3]):[0-5]\d$/.test(time);
}

function isValidUsername(name) {
  return /^[a-zA-Z0-9_]{3,20}$/.test(name);
}

function isStrongPassword(pwd) {
  return pwd.length >= 8 && /[A-Za-z]/.test(pwd) && /\d/.test(pwd);
}


const staticData = $getWorkflowStaticData('global');
if (!staticData.loginAttempts) staticData.loginAttempts = {};

const trigger = $('When Executed by Another Workflow').first().json;
const username = (trigger.username || '').trim();
const password = trigger.password || '';
const key = username.toLowerCase();

const attempts = staticData.loginAttempts[key] || { count: 0, lastAttempt: 0 };
const now = Date.now();
if (attempts.count >= 5 && now - attempts.lastAttempt < 15 * 60 * 1000) {
  return { json: { success: false, error: 'Trop de tentatives. Réessaie dans 15 minutes.', _update: false } };
}

const rows = $input.all().map(i => i.json);
const user = rows.find(r => (r.username || '').toLowerCase() === key);

if (!user) {
  attempts.count += 1;
  attempts.lastAttempt = now;
  staticData.loginAttempts[key] = attempts;
  return { json: { success: false, error: 'Identifiants incorrects.', _update: false } };
}

const hash = hashPassword(password, user.salt || '');
if (hash !== user.password_hash) {
  attempts.count += 1;
  attempts.lastAttempt = now;
  staticData.loginAttempts[key] = attempts;
  return { json: { success: false, error: 'Identifiants incorrects.', _update: false } };
}

if (user.active === false) {
  return { json: { success: false, error: 'Compte désactivé.', _update: false } };
}

staticData.loginAttempts[key] = { count: 0, lastAttempt: 0 };

const sessionToken = generateToken();
const expiresAt = tokenExpires(24);

return {
  json: {
    _update: true,
    rowId: user.id,
    session_token: sessionToken,
    session_expires_at: expiresAt,
    success: true,
    sessionToken,
    userId: user.id,
    username: user.username,
    error: null
  }
};
